.intro .interaction-intro{font-size:14px;line-height:1.6;color:#365a62;margin-top:18px;max-width:700px}.charts-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:35px}.chart-block{min-width:0;position:relative}.chart-block h3{font-size:17px;font-weight:500;line-height:1.5;color:#007485;margin:0 0 12px}.chart-controls{display:flex;flex-wrap:wrap;gap:10px 20px;align-items:flex-end;margin:8px 0 15px}.chart-controls label{font-size:12px;color:#45616a;display:flex;flex-direction:column;gap:6px}.chart-controls select{width:auto;max-width:100%;font-size:13px;min-height:36px;padding:5px 24px 5px 9px}.chart-reset{border:1px solid #bbcbcf;background:white;border-radius:3px;min-height:36px;padding:6px 12px;color:#244851;font-size:12px}.chart-reset:hover{background:#f0f5f6}.chart-legend{display:flex;flex-wrap:wrap;gap:5px 18px;margin:0 0 8px}.legend-toggle{display:inline-flex;align-items:center;gap:7px;background:none;border:0;padding:7px 0;min-height:32px;text-align:left;font-size:13px;color:#274851}.legend-toggle[aria-pressed="false"]{opacity:.45;text-decoration:line-through}.legend-swatch{width:19px;height:4px;display:inline-block;flex-shrink:0}.legend-toggle.pie-key .legend-swatch,.bar-key .legend-swatch{height:10px;width:12px}.bar-key{font-size:12px;display:inline-flex;align-items:center;gap:7px;margin-right:18px;min-height:30px;color:#45616a}.chart-hint{font-size:12px;line-height:1.5;color:#526b74;margin:0 0 9px}.live-plot{width:100%;height:480px;min-width:0}.chart-status{font-size:13px;color:#264a54;min-height:42px;line-height:1.6;padding:10px 12px;background:#eef5f6;border-left:3px solid #007485;margin:10px 0 0;overflow-wrap:anywhere}.chart-status:empty{display:none}.chart-source{font-size:12px;line-height:1.6;color:#456a74;margin-top:20px}.slide-notes{font-size:13px;line-height:1.65;color:#45616a}.slide-notes:empty{display:none}.slide-notes p{margin:8px 0}.original-slide{margin-top:15px}.methodology{font-size:16px;line-height:1.75;max-width:900px}.methodology p{margin:18px 0}.chart-loading{min-height:420px;display:flex;align-items:center;justify-content:center;color:#647c82;font-size:14px}.chart-error{padding:20px;background:#fff0f0;color:#a6192a}.transcript h4{font-size:14px;font-weight:500}.live-plot .modebar{z-index:1!important}.chart-unit{font-size:12px;color:#526b74;margin:10px 0 0}.chart-expanded{background:#fff;padding:12px}
@media(min-width:1100px){#slide-17 .charts-grid,#slide-23 .charts-grid{grid-template-columns:repeat(2,minmax(0,1fr))}#slide-17 .chart-block:first-child,#slide-23 .chart-block:first-child{grid-column:1/-1}}
@media(max-width:760px){.chart-controls{gap:12px}.chart-controls label{flex:1 1 160px;min-width:140px}.chart-controls select{width:100%;font-size:14px;min-height:44px}.chart-reset{min-height:44px}.chart-block h3{font-size:16px}.legend-toggle{min-height:44px;font-size:13px}.chart-legend{gap:0 15px}.chart-source{font-size:12px}.live-plot{height:410px}.chart-status{font-size:13px}.charts-grid{gap:28px}.methodology{font-size:15px}.chart-unit{font-size:12px}}

/* Prominent report title and country identifiers. */
.topbar .edition{display:block;font-size:clamp(24px,2.6vw,38px);font-weight:700;line-height:1.12;letter-spacing:-.025em;color:#007485;flex:1}
.country-label{display:inline-flex;align-items:center;gap:.28em;white-space:nowrap;vertical-align:baseline}.country-flag{width:1em;height:1em;min-width:16px;min-height:16px;max-width:25px;max-height:25px;border-radius:50%;object-fit:contain;display:inline-block;flex-shrink:0;vertical-align:middle}.live-plot{position:relative}.flag-layer{position:absolute;inset:0;pointer-events:none;z-index:3}.flag-layer .plot-flag{position:absolute;min-width:0;min-height:0;max-width:none;max-height:none}.legend-toggle .country-flag,.bar-key .country-flag,th .country-flag{width:20px;height:20px}.topbar{min-height:100px}
@media(max-width:760px){.topbar{flex-wrap:wrap;gap:12px;min-height:140px;padding:12px 18px}.topbar .edition{order:3;flex-basis:100%;border:0;padding:0;font-size:27px;line-height:1.08}.topbar #reading{order:2}.topbar .brand{order:1}:root{scroll-padding-top:166px}.country-label{gap:.22em}}


/* Reading layout, original palette. */
.topbar{background:var(--teal);border-color:var(--teal);color:white}.topbar .brand,.topbar .edition{color:white}.topbar .edition{border-left-color:#ffffff55}
.intro h1{white-space:nowrap;font-size:clamp(16px,2.8vw,42px);letter-spacing:-.035em}.chapter-introduction{font-size:clamp(25px,2.4vw,36px);line-height:1.25;font-weight:600;color:var(--teal);margin:0 0 36px;max-width:1000px}.chapter:first-of-type{font-size:18px;line-height:1.4}.chapter:first-of-type>span{display:none}
.title-frame{margin:0 0 22px}.title-frame h2{margin:0;font-size:clamp(25px,2.4vw,36px);transform:scale(.82);transform-origin:left top;will-change:transform}.chart-controls:empty{display:none}.chart-legend:empty{display:none}
@media(max-width:760px){nav .chapter:first-of-type{grid-column:1/-1;font-size:19px}nav .chapter:not(:first-of-type){grid-column:span 1}.intro h1{font-size:clamp(15px,4.1vw,30px)}.chapter-introduction{font-size:26px}.title-frame h2{font-size:25px}}
@media(prefers-reduced-motion:reduce){.title-frame h2{transform:none!important;will-change:auto}}

/* Fixed chapter navigation; the reading area uses the full width. */
.topbar{position:fixed;top:0;left:0;right:0;flex-wrap:wrap;gap:18px 28px;padding-bottom:0}.top-tabs{display:flex;gap:12px;flex-basis:100%;align-items:stretch}.top-tab{display:block;padding:12px 24px 15px;text-decoration:none;font-size:18px;font-weight:500;color:white;border-bottom:4px solid transparent}.top-tab.active{border-bottom-color:white;background:#ffffff14}.top-tab:hover{background:#ffffff1f}.layout{display:block;max-width:1280px;padding:0 4vw}.topbar .edition{order:initial}.topbar .brand{order:initial}
@media(max-width:760px){.topbar{gap:10px;padding-bottom:0}.topbar .edition{order:initial}.top-tabs{gap:0}.top-tab{font-size:15px;padding:12px 10px;flex:1;text-align:center}.layout{padding:0 18px}}

.chapter-introduction{font-weight:700}.chapter-highlight{background:#ce1126;color:#fff;padding:.02em .12em;box-decoration-break:clone;-webkit-box-decoration-break:clone}

.chapter-introduction{font-size:clamp(32px,3.2vw,48px);line-height:1.3;max-width:1150px}.chapter-highlight{padding:.035em .12em}.topbar .edition{font-size:clamp(28px,3vw,44px)}
@media(max-width:760px){.chapter-introduction{font-size:32px}.topbar .edition{font-size:30px}}

.topbar{background-image:url(data:image/png;base64,);background-size:100% 100%;background-position:center}
.chart-legend .legend-toggle,.chart-legend .bar-key{font-size:17px;gap:9px}.chart-legend .legend-swatch{width:15px;height:15px;border-radius:50%;clip-path:none}.chart-legend .us-swatch{background-image:repeating-linear-gradient(135deg,transparent 0 3px,#fff 3px 5px)!important}.plot-scroll{overflow-x:auto;max-width:100%}
.topbar{background-size:cover}

.year-underline{text-decoration:underline;text-decoration-thickness:.065em;text-underline-offset:.14em;text-decoration-skip-ink:auto}

.foreword{padding:38px 0 28px;border-bottom:1px solid var(--line);scroll-margin-top:18px}.foreword p{max-width:1000px;font-size:18px;line-height:1.7;margin:0 0 22px;color:#30535d}.chart-source{margin-top:12px}.slide-notes p{margin:6px 0}.chart-legend .us-swatch{background-color:white!important;background-image:repeating-linear-gradient(135deg,transparent 0 3px,#908296 3px 5px)!important}@media(max-width:760px){.top-tabs{flex-wrap:wrap}.top-tab{flex:1 1 auto}.foreword p{font-size:17px}}

